<script setup>

import {computed, onMounted, onUnmounted, ref, watch} from 'vue'

import {api, post} from '../api.js'


import {toast} from '../../shared/composables/toast.js'
const props=defineProps({connection:String})
const busy=ref(false),rules=ref(null),error=ref(''),optionsBusy=ref(false),optionsError=ref(''),valueOptions=ref({}),preview=ref(null),bugID=ref(''),previewBusy=ref(false),providers=ref([]),providerError=ref(''),saved=ref('')
let active=true
onUnmounted(()=>{active=false})
const fields=[{value:'kind',label:'工作项类型'},{value:'product',label:'所属产品'},{value:'project',label:'所属项目'},{value:'status',label:'来源状态'},{value:'resolution',label:'修复方案'},{value:'severity',label:'严重程度'},{value:'priority',label:'优先级'},{value:'title',label:'标题'}]
const decisions=[{value:'unknown',label:'待确认'},{value:'independent',label:'需上线'},{value:'not_independent',label:'无需上线'}]
const decisionLabel=d=>decisions.find(x=>x.value===d)?.label.replace('（推荐）','')||'待人工确认'
const providerOptions=computed(()=>[{value:'builtin',label:'通用条件规则（内置）'},...providers.value,...(rules.value?.provider&&rules.value.provider!=='builtin'&&!providers.value.some(x=>x.value===rules.value.provider)?[{value:rules.value.provider,label:rules.value.provider+'（未启用或不可用）'}]:[])])
const dirty=computed(()=>rules.value&&JSON.stringify(rules.value)!==saved.value)
const selectedUnavailable=computed(()=>rules.value?.provider!=='builtin'&&!providers.value.some(x=>x.value===rules.value?.provider))
watch(rules,()=>{preview.value=null},{deep:true})
watch(bugID,()=>{preview.value=null})
function valueChoices(field){return Object.entries(valueOptions.value[field]||{}).filter(([v])=>v!=='').map(([value,label])=>({value,label:label===value?label:label+' · '+value}))}
async function load(){busy.value=true;error.value='';try{const v=await api('research/connections/'+encodeURIComponent(props.connection)+'/release-rules');if(!active)return;rules.value=v;rules.value.provider||='builtin';saved.value=JSON.stringify(rules.value)}catch(e){if(active){error.value=e.message;toast(e.message,'error')}}finally{if(active)busy.value=false}}
async function loadProviders(){providerError.value='';try{const res=await api('/api/extensions');if(active)providers.value=(res||[]).filter(x=>x.state==='running'&&x.manifest?.capabilities?.includes('policy.release.v1')).map(x=>({value:x.manifest.id,label:x.manifest.name+' · '+x.manifest.version}))}catch(e){if(active)providerError.value='插件列表读取失败，可重试'}}
async function loadOptions(){optionsBusy.value=true;optionsError.value='';try{const v=await api('research/connections/'+encodeURIComponent(props.connection)+'/release-rules/options');if(active)valueOptions.value=v.options||{}}catch(e){if(active)optionsError.value=e.message}finally{if(active)optionsBusy.value=false}}
function addRule(){rules.value.policy.rules.push({name:'',match:'all',conditions:[{field:'project',operator:'in',values:[]}],decision:'independent'})}
function changeField(c){c.values=[];c.operator='in'}
function move(i,by){const a=rules.value.policy.rules;[a[i],a[i+by]]=[a[i+by],a[i]]}
function validate(){for(const [i,r] of rules.value.policy.rules.entries()){if(!r.name.trim()||r.conditions.some(c=>!c.values.length||c.values.some(v=>!v.trim()))){toast('请补全第 '+(i+1)+' 条规则的名称和条件值','error');return false}}return true}
async function save(){if(busy.value||!validate())return;busy.value=true;try{const v=await post('research/connections/'+encodeURIComponent(props.connection)+'/release-rules',rules.value,'PUT');if(!active)return;rules.value=v;saved.value=JSON.stringify(v);toast('规则已保存；人工调整和已冻结交付范围保持原样','success')}catch(e){toast(e.message,'error')}finally{if(active)busy.value=false}}
async function runPreview(){if(previewBusy.value||!validate())return;previewBusy.value=true;try{const v=await post('research/connections/'+encodeURIComponent(props.connection)+'/release-rules/preview',{...rules.value,bug_id:bugID.value.trim()});if(active)preview.value=v}catch(e){toast(e.message,'error')}finally{if(active)previewBusy.value=false}}
onMounted(()=>{load();loadProviders();loadOptions()})

import OptionPicker from '../../shared/components/OptionPicker.vue'



import {Button,Checkbox,Field,FieldLabel,Input,Spinner} from '../../shared/shadcn-ui.js'
</script>
<template><div v-if="rules" :aria-busy="busy" class="rule-settings"><div class="rule-header"><label class="rule-switch"><Checkbox v-model="rules.enabled" :disabled="busy||previewBusy"/>自动识别是否需上线</label><span class="r-muted">人工调整优先；这里只判断交付意图，不执行发布。</span></div><div class="rule-controls"><Field ><FieldLabel as="div">规则提供方</FieldLabel><OptionPicker v-model="rules.provider" :options="providerOptions" :disabled="busy||previewBusy" :style="{width:'280px',maxWidth:'100%'}"/></Field><Button @click="loadProviders" variant="ghost" size="default" type="button" :disabled="(busy)">刷新插件</Button><small v-if="providerError" role="status">{{providerError}}</small></div><p v-if="selectedUnavailable" role="status" class="r-muted">规则插件当前不可用。已保存规则继续生效；编辑后需恢复插件，或明确切换到内置规则。</p><div class="rule-guide"><strong>配置方法</strong><span>选字段和条件值 → 选择判定结果 → 用 Bug 编号预览 → 保存。多条规则从上到下匹配，先命中的生效。</span></div><div class="rule-options"><small class="r-muted">{{optionsBusy?'正在读取来源选项…':optionsError?'来源选项未读到：'+optionsError:'优先选择来源平台返回的名称；没有选项时可输入已核对的编码，回车添加。'}}</small><Button @click="loadOptions" variant="ghost" size="default" type="button" :disabled="(optionsBusy||busy)">重新读取选项</Button></div><div v-if="!rules.policy.rules.length" class="rules-empty">尚未添加规则。启用后未命中的工作项按下方默认结果处理。</div><article v-for="(rule,i) in rules.policy.rules" :key="i" class="policy-rule"><div class="rule-title"><span>{{i+1}}.</span><Input v-model="rule.name" placeholder="规则名称，例如：生产问题需单独上线" :disabled="busy||previewBusy" v-bind="{&quot;aria-label&quot;:('规则 '+(i+1)+' 名称')}"/><Button @click="move(i,-1)" variant="ghost" size="default" type="button" :disabled="(busy||previewBusy||i===0)">上移</Button><Button @click="move(i,1)" variant="ghost" size="default" type="button" :disabled="(busy||previewBusy||i===rules.policy.rules.length-1)">下移</Button><Button @click="rules.policy.rules.splice(i,1)" variant="ghost" size="default" type="button" :disabled="(busy||previewBusy)">移除</Button></div><div class="rule-match"><span>当</span><OptionPicker v-model="rule.match" :options="[{value:'all',label:'满足全部条件'},{value:'any',label:'满足任一条件'}]" :disabled="busy||previewBusy" :style="{width:'170px',maxWidth:'100%'}"/></div><div v-for="(c,j) in rule.conditions" :key="j" class="condition-row"><OptionPicker v-model="c.field" :options="fields" :disabled="busy||previewBusy" :style="{width:'150px',maxWidth:'100%'}" :aria-label="'规则 '+(i+1)+' 条件字段'" @change="changeField(c)"/><OptionPicker v-model="c.operator" :options="[{value:'in',label:'是以下任一值'},{value:'not_in',label:'不是以下值'},...(c.field==='title'?[{value:'contains',label:'包含文字'}]:[])]" :disabled="busy||previewBusy" :style="{width:'155px',maxWidth:'100%'}" @change="c.values=[]"/><Input v-if="c.operator==='contains'" :model-value="c.values[0]||''" placeholder="输入标题包含的文字（区分大小写）" :disabled="busy||previewBusy" @update:model-value="c.values=[$event]"/><OptionPicker v-else v-model="c.values" multiple :disabled="busy||previewBusy" placeholder="选择名称，或输入编码后回车" :aria-label="'规则 '+(i+1)+' 条件值'" class="min-w-36" :options="[...(valueChoices(c.field)).map((v)=>({value:v.value,label:v.label}))]" allow-create/><Button @click="rule.conditions.splice(j,1)" variant="ghost" size="default" type="button" :disabled="(busy||previewBusy||rule.conditions.length===1)">删除条件</Button></div><div class="rule-result"><Button @click="rule.conditions.push({field:'kind',operator:'in',values:[]})" variant="ghost" size="default" type="button" :disabled="(busy||previewBusy||rule.conditions.length>=8)">＋ 条件</Button><Field ><FieldLabel as="div">则判定为</FieldLabel><OptionPicker v-model="rule.decision" :options="decisions" :disabled="busy||previewBusy" :style="{width:'250px',maxWidth:'100%'}"/></Field></div></article><Button @click="addRule" class="add-rule" variant="outline" size="default" type="button" :disabled="(busy||previewBusy||rules.policy.rules.length>=100)">＋ 添加识别规则</Button><div class="rule-default"><Field ><FieldLabel as="div">没有命中规则时</FieldLabel><OptionPicker v-model="rules.policy.default" :options="decisions" :disabled="busy||previewBusy" :style="{width:'250px',maxWidth:'100%'}"/></Field><small class="r-muted">条件所需字段缺失时保持待确认，不自动判为无需上线。</small></div><div v-if="rules.policy.required_fields?.length" class="r-muted">原有规则保留前置字段：{{rules.policy.required_fields.map(f=>fields.find(v=>v.value===f)?.label||f).join('、')}}。<Button @click="rules.policy.required_fields=[]" variant="ghost" size="default" type="button" :disabled="(busy||previewBusy)">改为仅检查每条规则所需字段</Button></div><section class="policy-preview"><strong>保存前试一下</strong><div class="preview-controls"><Input v-model="bugID" placeholder="当前来源的 Bug 编号" :disabled="busy||previewBusy" @keydown.enter="runPreview" v-bind="{&quot;aria-label&quot;:&quot;预览 Bug 编号&quot;}"/><Button @click="runPreview" variant="outline" size="default" type="button" :disabled="(busy||selectedUnavailable||!bugID.trim())||(previewBusy)"><Spinner v-if="previewBusy"/>预览判定</Button></div><div v-if="preview" role="status" class="preview-result"><strong>#{{preview.bug_id}} · {{preview.title}}</strong><b>自动识别：{{decisionLabel(preview.result.decision)}}</b><span>{{preview.result.reason}}</span><b v-if="preview.effective_result?.reason!==preview.result.reason">人工调整优先：{{decisionLabel(preview.effective_result.decision)}}</b><span v-if="preview.effective_result?.reason!==preview.result.reason">{{preview.effective_result.reason}}</span><small>{{preview.note}}</small></div></section><div class="rule-footer"><span class="r-muted">{{dirty?'有未保存的修改':'已保存 · 版本 '+rules.revision}}</span><Button @click="save" variant="default" size="default" type="button" :disabled="(previewBusy||selectedUnavailable||!dirty)||(busy)"><Spinner v-if="busy"/>保存识别规则</Button></div></div><div v-else role="status">{{error||'正在读取规则…'}}<Button v-if="error" @click="load" variant="outline" size="default" type="button">重试</Button></div></template>
<style scoped>.rule-settings{display:grid;gap:16px;margin-top:16px}.rule-header,.rule-controls,.rule-title,.rule-match,.rule-result,.condition-row,.rule-default,.rule-footer,.rule-options,.preview-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.rule-header{justify-content:space-between}.rule-switch,.rule-controls label,.rule-default label,.rule-result label{display:flex;align-items:center;gap:10px}.rule-switch{font-weight:600}.rule-guide{display:grid;gap:5px;padding:12px 14px;background:var(--panel2);border-radius:var(--radius)}.rule-guide span,.rule-options,.r-muted{font-size:.75rem;color:var(--muted-foreground)}.policy-rule{display:grid;gap:12px;padding:16px;border:1px solid var(--border);border-radius:var(--radius)}.rule-result{justify-content:space-between}.rules-empty{padding:20px;text-align:center;color:var(--muted-foreground)}.add-rule{justify-self:start}.policy-preview{border-top:1px solid var(--border);padding-top:16px;display:grid;gap:12px}.preview-result{display:grid;gap:6px;border-left:3px solid var(--brand);padding:8px 12px;background:var(--panel2)}.preview-result small{color:var(--muted-foreground)}.rule-footer{justify-content:space-between;border-top:1px solid var(--border);padding-top:14px}.rule-default{padding:8px 0}@media(max-width:650px){.rule-controls label,.rule-default label,.rule-result label{width:100%;align-items:flex-start;flex-direction:column}.rule-header{align-items:flex-start;flex-direction:column}}</style>
